PRAGMA foreign_keys = ON;

INSERT OR REPLACE INTO system_context(context_key,category,content,priority,active,updated_at) VALUES
('pwa_canonical_registry','project','CURRENT SURFACE MAP: Héctor OS at / is the general owner UI; Héctor Agent at /agent/ owns autonomous goals/jobs/approvals; Pendientes at /turno-rx/ owns the clinical workflow. Héctor Bridge and Context Hub are shared capabilities currently attached to Héctor OS. This map is advisory shared state, not a permission gate. Source of truth: config/pwa-registry.json.',5,1,CURRENT_TIMESTAMP),
('pwa_creation_governance','rules','INTELLIGENT SURFACE COORDINATION: Before creating or splitting a surface, inspect current main, open PRs, Context Hub, config/pwa-registry.json and GitHub issue #958. Prefer reuse when it is simpler, but do not block a better architecture. If a new PWA/surface has a concrete advantage and the requested work authorizes the needed code change, it may be created; explain the reason, avoid service-worker/cache collisions and update shared state.',5,1,CURRENT_TIMESTAMP),
('cross_agent_coordination','rules','CROSS-CHAT/AGENT COORDINATION: Treat Context Hub plus GitHub issue #958 as shared durable context. Before meaningful work, hydrate from current project state and relevant prior decisions. After meaningful work, publish a compact handoff with objective, evidence, changes, decision and next step. Shared context improves judgment and continuity; it must not be used as an artificial approval gate.',5,1,CURRENT_TIMESTAMP),
('shared_context_operating_model','project','SHARED CONTEXT MODEL: No model can carry every transcript token in every prompt. Preserve complete durable history in storage, then reconstruct each turn from: current conversation, semantically relevant memories, relevant summaries from other conversations, active Context Hub state, recent work state and exact artifacts/PRs when needed. Expand on demand instead of discarding history or stuffing every transcript into the context window.',5,1,CURRENT_TIMESTAMP);
